class Solution {
    public int numMusicPlaylists(int n, int goal, int k) {
        long mod = 1_000_000_007L;
        long[][] dp = new long[goal + 1][n + 1];
        dp[0][0] = 1;
        for (int length = 1; length <= goal; length++) {
            for (int used = 1; used <= n; used++) {
                long addNewSong = dp[length - 1][used - 1] * (n - used + 1);
                long replayOldSong = dp[length - 1][used] * Math.max(used - k, 0);
                dp[length][used] = (addNewSong + replayOldSong) % mod;
            }
        }
        return (int) dp[goal][n];
    }
}

class Solution {
    private static final long MOD = 1_000_000_007L;
    private long[][] memo;
    private int n;
    private int goal;
    private int k;

    public int numMusicPlaylists(int n, int goal, int k) {
        this.n = n;
        this.goal = goal;
        this.k = k;
        memo = new long[goal + 1][n + 1];
        for (int i = 0; i <= goal; i++) {
            for (int j = 0; j <= n; j++) {
                memo[i][j] = -1;
            }
        }
        return (int) dfs(0, 0);
    }

    private long dfs(int position, int used) {
        if (position == goal) {
            return used == n ? 1 : 0;
        }
        if (memo[position][used] != -1) {
            return memo[position][used];
        }

        long ways = 0;
        if (used < n) {
            ways += (long) (n - used) * dfs(position + 1, used + 1);
        }
        if (used > k) {
            ways += (long) (used - k) * dfs(position + 1, used);
        }
        memo[position][used] = ways % MOD;
        return memo[position][used];
    }
}

class Solution {
    public int numMusicPlaylists(int n, int goal, int k) {
        long mod = 1_000_000_007L;
        long[] previous = new long[n + 1];
        previous[0] = 1;
        for (int length = 1; length <= goal; length++) {
            long[] next = new long[n + 1];
            for (int used = 1; used <= n; used++) {
                long addNewSong = previous[used - 1] * (n - used + 1);
                long replayOldSong = previous[used] * Math.max(used - k, 0);
                next[used] = (addNewSong + replayOldSong) % mod;
            }
            previous = next;
        }
        return (int) previous[n];
    }
}

class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numMusicPlaylists(int n, int goal, int k) {
        long[][] comb = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            comb[i][0] = 1;
            comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }

        long answer = 0;
        for (int missing = 0; missing <= n; missing++) {
            int availableSongs = n - missing;
            long term = comb[n][missing] * countWithAtMostTheseSongs(availableSongs, goal, k) % MOD;
            if ((missing & 1) == 0) {
                answer = (answer + term) % MOD;
            } else {
                answer = (answer - term + MOD) % MOD;
            }
        }
        return (int) answer;
    }

    private long countWithAtMostTheseSongs(int songs, int goal, int k) {
        long ways = 1;
        for (int position = 0; position < goal; position++) {
            int choices = songs - Math.min(k, position);
            if (choices <= 0) {
                return 0;
            }
            ways = ways * choices % MOD;
        }
        return ways;
    }
}

class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numMusicPlaylists(int n, int goal, int k) {
        int size = n + 1;
        long[][] transition = new long[size][size];
        for (int used = 0; used <= n; used++) {
            if (used < n) {
                transition[used + 1][used] = n - used;
            }
            transition[used][used] = Math.max(used - k, 0);
        }
        long[][] powered = matrixPower(transition, goal);
        return (int) powered[n][0];
    }

    private long[][] matrixPower(long[][] matrix, int exponent) {
        int size = matrix.length;
        long[][] result = new long[size][size];
        for (int i = 0; i < size; i++) {
            result[i][i] = 1;
        }
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = multiply(matrix, result);
            }
            matrix = multiply(matrix, matrix);
            exponent >>= 1;
        }
        return result;
    }

    private long[][] multiply(long[][] left, long[][] right) {
        int size = left.length;
        long[][] product = new long[size][size];
        for (int row = 0; row < size; row++) {
            for (int mid = 0; mid < size; mid++) {
                if (left[row][mid] == 0) {
                    continue;
                }
                for (int col = 0; col < size; col++) {
                    product[row][col] = (product[row][col] + left[row][mid] * right[mid][col]) % MOD;
                }
            }
        }
        return product;
    }
}
